    26→  traits: z.array(z.string()).optional(),
    27→  implementation_notes: z.string().min(1).optional(),
    28→});
    29→
    30→export type PlanSpec = z.infer<typeof PlanSpecSchema>;
    31→
    32→/**
    33→ * Manual task definition from plan document
    34→ */
    35→export const PlanTaskSchema = z.object({
    36→  title: z.string(),
    37→  slug: z.string().optional(),
    38→  priority: z.number().optional(),
    39→  description: z.string().optional(),
    40→  tags: z.array(z.string()).optional(),
    41→  spec_ref: z.string().optional(),
    42→});
    43→
    44→export type PlanTask = z.infer<typeof PlanTaskSchema>;
    45→
    46→/**
    47→ * Tasks section configuration
    48→ */
    49→export const TasksSectionSchema = z.object({
    50→  derive_from_specs: z.boolean().optional(),
    51→  additional_tasks: z.array(PlanTaskSchema).optional(),
    52→});
    53→
    54→export type TasksSection = z.infer<typeof TasksSectionSchema>;
    55→
    56→/**
    57→ * Parsed plan document structure
    58→ */
    59→export interface ParsedPlanDocument {
    60→  title: string;
    61→  content: string;
    62→  specs: PlanSpec[];
    63→  tasks: TasksSection;
    64→  implementationNotes: string | null;
    65→  errors: ParseError[];
    66→}
    67→
    68→/**
    69→ * Parse error with context
    70→ */
    71→export interface ParseError {
    72→  type: "yaml" | "validation" | "dependency" | "circular";
    73→  message: string;
    74→  line?: number;
    75→  specIndex?: number;
    76→  spec?: PlanSpec;
    77→}
    78→
    79→/**
    80→ * Parse a plan document from markdown text.
    81→ *
    82→ * AC: @plan-import ac-11 - Extract and parse ## Specs YAML blocks
    83→ * AC: @plan-import ac-12 - Parse Tasks section for derive_from_specs
    84→ * AC: @plan-import ac-13 - Extract ## Implementation Notes section
    85→ * AC: @plan-import ac-21 - Report YAML parse errors with line numbers
    86→ */
    87→export function parsePlanDocument(content: string): ParsedPlanDocument {
    88→  const errors: ParseError[] = [];
    89→
    90→  // Extract title from first heading
    91→  const titleMatch = content.match(/^#\s+(.+)$/m);
    92→  const title = titleMatch ? titleMatch[1].trim() : "Untitled Plan";
    93→
    94→  // Extract ## Specs section
    95→  const specs = extractSpecsSection(content, errors);
    96→
    97→  // Extract ## Tasks section
    98→  const tasks = extractTasksSection(content, errors);
    99→
   100→  // Extract ## Implementation Notes section
   101→  const implementationNotes = extractImplementationNotes(content);
   102→
   103→  return {
   104→    title,
   105→    content,
   106→    specs,
   107→    tasks,
   108→    implementationNotes,
   109→    errors,
   110→  };
   111→}
   112→
   113→/**
   114→ * Extract and parse the ## Specs section.
   115→ *
   116→ * AC: @plan-import ac-11 - Parse YAML array of spec definitions
   117→ * AC: @plan-import ac-21 - Handle YAML parse errors
   118→ * AC: @plan-import ac-22 - Validate required fields
   119→ */
   120→function extractSpecsSection(content: string, errors: ParseError[]): PlanSpec[] {
   121→  // Find ## Specs section
   122→  const specsMatch = content.match(/##\s+Specs\s*\n([\s\S]*?)(?=\n##\s+\w|$)/);
   123→
   124→  if (!specsMatch) {
   125→    return [];
   126→  }
   127→
   128→  const specsContent = specsMatch[1];
   129→
   130→  // Extract YAML code block
   131→  const yamlMatch = specsContent.match(/```(?:yaml)?\s*\n([\s\S]*?)\n```/);
   132→
   133→  if (!yamlMatch) {
   134→    errors.push({
   135→      type: "validation",
   136→      message:
   137→        "Specs section found but contains no YAML code block. Wrap specs in ```yaml ... ```",
   138→    });
   139→    return [];
   140→  }
   141→
   142→  const yamlContent = yamlMatch[1];
   143→
   144→  // Parse YAML
   145→  let parsed: unknown;
   146→  try {
   147→    parsed = parseYaml(yamlContent);
   148→  } catch (err) {
   149→    errors.push({
   150→      type: "yaml",
   151→      message: `Malformed YAML in Specs section: ${err instanceof Error ? err.message : String(err)}`,
   152→    });
   153→    return [];
   154→  }
   155→
   156→  // Validate array
   157→  if (!Array.isArray(parsed)) {
   158→    errors.push({
   159→      type: "validation",
   160→      message: "Specs section must contain a YAML array",
   161→    });
   162→    return [];
   163→  }
   164→
   165→  // Validate each spec
   166→  const specs: PlanSpec[] = [];
   167→
   168→  for (let i = 0; i < parsed.length; i++) {
   169→    const spec = parsed[i];
   170→
   171→    // Validate required title field
   172→    if (!spec || typeof spec !== "object" || !("title" in spec)) {
   173→      errors.push({
   174→        type: "validation",
   175→        message: `Spec at index ${i} missing required field: title`,
   176→        specIndex: i,
   177→      });
   178→      continue;
   179→    }
   180→
   181→    // Validate against schema
   182→    const result = PlanSpecSchema.safeParse(spec);
   183→    if (!result.success) {
   184→      errors.push({
   185→        type: "validation",
   186→        message: `Spec at index ${i} validation failed: ${result.error.message}`,
   187→        specIndex: i,
   188→      });
   189→      continue;
   190→    }
   191→
   192→    specs.push(result.data);
   193→  }
   194→
   195→  return specs;
   196→}
   197→
   198→/**
   199→ * Extract and parse the ## Tasks section.
   200→ *
   201→ * AC: @plan-import ac-12 - Parse derive_from_specs flag
   202→ * AC: @plan-import ac-27 - Parse additional_tasks array
   203→ */
   204→function extractTasksSection(content: string, errors: ParseError[]): TasksSection {
   205→  // Find ## Tasks section
   206→  const tasksMatch = content.match(/##\s+Tasks\s*\n([\s\S]*?)(?=\n##\s+\w|$)/);
   207→
   208→  if (!tasksMatch) {
   209→    return {};
   210→  }
   211→
   212→  const tasksContent = tasksMatch[1].trim();
   213→
   214→  // Check for derive_from_specs flag
   215→  const deriveMatch = tasksContent.match(/^derive_from_specs:\s*(true|false)/m);
   216→  const deriveFromSpecs = deriveMatch ? deriveMatch[1] === "true" : undefined;
   217→
   218→  // Extract YAML code block for additional tasks
   219→  const yamlMatch = tasksContent.match(/```(?:yaml)?\s*\n([\s\S]*?)\n```/);
   220→
   221→  let additionalTasks: PlanTask[] | undefined;
   222→
   223→  if (yamlMatch) {
   224→    const yamlContent = yamlMatch[1];
   225→
   226→    try {
   227→      const parsed = parseYaml(yamlContent);
   228→
   229→      if (Array.isArray(parsed)) {
   230→        additionalTasks = [];
   231→        for (let i = 0; i < parsed.length; i++) {
   232→          const result = PlanTaskSchema.safeParse(parsed[i]);
   233→          if (!result.success) {
   234→            errors.push({
   235→              type: "validation",
   236→              message: `Task at index ${i} validation failed: ${result.error.message}`,
   237→            });
   238→            continue;
   239→          }
   240→          additionalTasks.push(result.data);
   241→        }
   242→      }
   243→    } catch (err) {
   244→      errors.push({
   245→        type: "yaml",
   246→        message: `Malformed YAML in Tasks section: ${err instanceof Error ? err.message : String(err)}`,
   247→      });
   248→    }
   249→  }
   250→
   251→  return {
   252→    derive_from_specs: deriveFromSpecs,
   253→    additional_tasks: additionalTasks,
   254→  };
   255→}
   256→
   257→/**
   258→ * Extract ## Implementation Notes section.
   259→ *
   260→ * AC: @plan-import ac-13 - Extract implementation notes as plain text
   261→ */
   262→function extractImplementationNotes(content: string): string | null {
   263→  const notesMatch = content.match(/##\s+Implementation\s+Notes\s*\n([\s\S]*?)(?=\n##\s+\w|$)/);
   264→
   265→  if (!notesMatch) {
   266→    return null;
   267→  }
   268→
   269→  return notesMatch[1].trim();
   270→}
   271→
   272→/**
   273→ * Sort specs in topological order (parents before children).
   274→ *
   275→ * AC: @plan-import ac-16 - Create specs in dependency order
   276→ * AC: @plan-import ac-18 - Detect circular dependencies
   277→ *
   278→ * @returns Sorted specs or null if circular dependency detected
   279→ */
   280→export function topologicalSort(
   281→  specs: PlanSpec[],
   282→): { sorted: PlanSpec[]; error: ParseError | null } {
   283→  // Build adjacency list
   284→  const graph = new Map<string, string[]>();
   285→  const specBySlug = new Map<string, PlanSpec>();
   286→
   287→  for (const spec of specs) {
   288→    const slug = spec.slug || slugify(spec.title);
   289→    if (specBySlug.has(slug)) {
   290→      return {
   291→        sorted: [],
   292→        error: {
   293→          type: "validation",
   294→          message: `Duplicate slug detected: "${slug}". Ensure each spec has a unique slug or title.`,
   295→        },
   296→      };
   297→    }
   298→    specBySlug.set(slug, spec);
   299→    graph.set(slug, []);
   300→  }
   301→
   302→  // Add edges for parent dependencies
   303→  for (const spec of specs) {
   304→    const slug = spec.slug || slugify(spec.title);
   305→    if (spec.parent) {
   306→      const parentRef = spec.parent.startsWith("@") ? spec.parent.slice(1) : spec.parent;
   307→
   308→      // Only add edge if parent is in this plan (local reference)
   309→      if (specBySlug.has(parentRef)) {
   310→        const children = graph.get(parentRef) || [];
   311→        children.push(slug);
   312→        graph.set(parentRef, children);
   313→      }
   314→    }
   315→  }
   316→
   317→  // Detect cycles using DFS
   318→  const visited = new Set<string>();
   319→  const recursionStack = new Set<string>();
   320→
   321→  function hasCycle(node: string, path: string[]): string[] | null {
   322→    visited.add(node);
   323→    recursionStack.add(node);
   324→
   325→    const children = graph.get(node) || [];
   326→    for (const child of children) {
   327→      if (!visited.has(child)) {
   328→        const cyclePath = hasCycle(child, [...path, child]);
   329→        if (cyclePath) return cyclePath;
   330→      } else if (recursionStack.has(child)) {
   331→        return [...path, child];
   332→      }
   333→    }
   334→
   335→    recursionStack.delete(node);
   336→    return null;
   337→  }
   338→
   339→  for (const slug of graph.keys()) {
   340→    if (!visited.has(slug)) {
   341→      const cyclePath = hasCycle(slug, [slug]);
   342→      if (cyclePath) {
   343→        const cycleRefs = cyclePath.map(s => `@${s}`).join(" -> ");
   344→        return {
   345→          sorted: [],
   346→          error: {
   347→            type: "circular",
   348→            message: `Circular parent reference: ${cycleRefs}`,
   349→          },
   350→        };
   351→      }
   352→    }
   353→  }
   354→
   355→  // Topological sort using DFS
   356→  const sorted: PlanSpec[] = [];
   357→  const processed = new Set<string>();
   358→
   359→  function visit(node: string) {
   360→    if (processed.has(node)) return;
   361→
   362→    const spec = specBySlug.get(node);
   363→    if (!spec) return;
   364→
   365→    // Visit parent first if it's in this plan
   366→    if (spec.parent) {
   367→      const parentRef = spec.parent.startsWith("@") ? spec.parent.slice(1) : spec.parent;
   368→      if (specBySlug.has(parentRef)) {
   369→        visit(parentRef);
   370→      }
   371→    }
   372→
   373→    processed.add(node);
   374→    sorted.push(spec);
   375→  }
   376→
   377→  for (const slug of specBySlug.keys()) {
   378→    visit(slug);
   379→  }
   380→
   381→  return { sorted, error: null };
   382→}
   383→
   384→/**
   385→ * Simple slugification helper
   386→ */
   387→function slugify(title: string): string {
   388→  return title
   389→    .toLowerCase()
   390→    .replace(/[^a-z0-9]+/g, "-")
   391→    .replace(/^-|-$/g, "");
   392→}
   393→
   394→/**
   395→ * Validate parent references.
   396→ *
   397→ * AC: @plan-import ac-17 - Detect missing parent references
   398→ * AC: @plan-import ac-33 - Provide recovery hints
   399→ *
   400→ * @param specs Specs to validate
   401→ * @param existingRefs Set of existing spec refs in the project
   402→ * @returns Errors for specs with invalid parents
   403→ */
   404→export function validateParentRefs(
   405→  specs: PlanSpec[],
   406→  existingRefs: Set<string>,
   407→): ParseError[] {
   408→  const errors: ParseError[] = [];
   409→  const planSlugs = new Set(
   410→    specs.map(s => s.slug || slugify(s.title))
   411→  );
   412→
   413→  for (const spec of specs) {
   414→    if (!spec.parent) continue;
   415→
   416→    const parentRef = spec.parent.startsWith("@") ? spec.parent.slice(1) : spec.parent;
   417→
   418→    // Check if parent exists in plan or project
   419→    if (!planSlugs.has(parentRef) && !existingRefs.has(parentRef)) {
   420→      errors.push({
   421→        type: "dependency",
   422→        message: `Parent ${spec.parent} not found. Check parent exists or define it earlier in plan`,
   423→        spec,
   424→      });
   425→    }
   426→  }
   427→
   428→  return errors;
   429→}
   430→
