114→/**
115→ * Acquire a simple mkdir-based file lock. Returns a release function.
116→ * Uses mkdir atomicity on POSIX filesystems to prevent concurrent writes.
117→ * Writes PID to a file inside the lock dir for staleness detection.
118→ */
119→async function acquireLock(
120→  lockPath: string,
121→  timeoutMs = 5000,
122→): Promise<() => Promise<void>> {
123→  const pidFile = path.join(lockPath, "pid");
124→  const start = Date.now();
125→
126→  while (true) {
127→    try {
128→      await fs.mkdir(lockPath);
129→      // Write our PID for staleness detection
130→      await fs.writeFile(pidFile, String(process.pid));
131→      return async () => {
132→        try {
133→          await fs.rm(lockPath, { recursive: true });
134→        } catch {
135→          // Lock already released
136→        }
137→      };
138→    } catch {
139→      if (Date.now() - start > timeoutMs) {
140→        // Check if lock holder is still alive before force-removing
141→        let isStale = false;
142→        try {
143→          const holderPid = parseInt(await fs.readFile(pidFile, "utf-8"), 10);
144→          if (!isNaN(holderPid)) {
145→            try {
146→              process.kill(holderPid, 0); // signal 0 = check existence
147→            } catch {
148→              isStale = true; // Process doesn't exist — lock is stale
149→            }
150→          } else {
151→            isStale = true; // Corrupt PID file
152→          }
153→        } catch {
154→          isStale = true; // No PID file — assume stale
155→        }
156→
157→        if (isStale) {
158→          try {
159→            await fs.rm(lockPath, { recursive: true });
160→          } catch {
161→            // ignore
162→          }
163→          // Retry once after stale lock removal
164→          try {
165→            await fs.mkdir(lockPath);
166→            await fs.writeFile(pidFile, String(process.pid));
167→            return async () => {
168→              try {
169→                await fs.rm(lockPath, { recursive: true });
170→              } catch {
171→                // Lock already released
172→              }
173→            };
174→          } catch {
175→            throw new Error(`Failed to acquire lock: ${lockPath}`);
176→          }
177→        }
178→        throw new Error(`Lock held by active process, timeout after ${timeoutMs}ms: ${lockPath}`);
179→      }
180→      await new Promise((r) => setTimeout(r, 50));
181→    }
182→  }
183→}
