    18→import { normalizeRefInput } from "../../schema/index.js";
    19→import type { TaskInput } from "../../schema/index.js";
    20→import { errors } from "../../strings/index.js";
    21→import { EXIT_CODES } from "../exit-codes.js";
    22→import { error, info, isJsonMode, output, warn } from "../output.js";
    23→import { parseIntOption } from "../validators.js";
    24→
    25→/**
    26→ * Fields that contain nested spec items (mirrors yaml.ts)
    27→ */
    28→const _NESTED_ITEM_FIELDS = [
    29→  "modules",
    30→  "features",
    31→  "requirements",
    32→  "constraints",
    33→  "decisions",
    34→];
    35→
    36→/**
    37→ * Get the parent path from a child's _path.
    38→ * e.g., "features[0].requirements[1]" -> "features[0]"
    39→ * Returns empty string for top-level items.
    40→ */
    41→function getParentPath(childPath: string | undefined): string {
    42→  if (!childPath) return "";
    43→  const lastDotIndex = childPath.lastIndexOf(".");
    44→  if (lastDotIndex === -1) return "";
    45→  return childPath.slice(0, lastDotIndex);
    46→}
    47→
    48→/**
    49→ * Check if an item is a direct child of another item based on _path.
    50→ * Direct children have a path that extends the parent's path by exactly one field[index].
    51→ */
    52→function isDirectChildOf(
    53→  child: LoadedSpecItem,
    54→  parent: LoadedSpecItem,
    55→): boolean {
    56→  const childPath = child._path || "";
    57→  const parentPath = parent._path || "";
    58→
    59→  // If paths are equal, not a child
    60→  if (childPath === parentPath) return false;
    61→
    62→  // Child path must start with parent path
    63→  if (parentPath && !childPath.startsWith(`${parentPath}.`)) return false;
    64→
    65→  // For root parent (empty path), child must be a top-level path like "features[0]"
    66→  if (!parentPath) {
    67→    // Direct child of root has no '.' in its path
    68→    return !childPath.includes(".");
    69→  }
    70→
    71→  // Get the remaining path after parent
    72→  const remaining = childPath.slice(parentPath.length + 1);
    73→
    74→  // Direct child has no additional '.' (e.g., "requirements[0]" not "requirements[0].something")
    75→  return !remaining.includes(".");
    76→}
    77→
    78→/**
    79→ * Find the parent spec item of a given item.
    80→ * Returns undefined for root-level items.
    81→ */
    82→function findParentItem(
    83→  item: LoadedSpecItem,
    84→  allItems: LoadedSpecItem[],
    85→): LoadedSpecItem | undefined {
    86→  const parentPath = getParentPath(item._path);
    87→
    88→  // Root-level item or no path
    89→  if (!parentPath && !item._path) return undefined;
    90→  if (!parentPath) return undefined;
    91→
    92→  // Find item with matching path in the same source file
    93→  return allItems.find(
    94→    (i) => i._path === parentPath && i._sourceFile === item._sourceFile,
    95→  );
    96→}
    97→
    98→/**
    99→ * Get direct children of a spec item.
   100→ * Only returns immediate children, not grandchildren.
   101→ */
   102→function getDirectChildren(
   103→  parent: LoadedSpecItem,
   104→  allItems: LoadedSpecItem[],
   105→): LoadedSpecItem[] {
   106→  return allItems.filter(
   107→    (item) =>
   108→      item._sourceFile === parent._sourceFile && isDirectChildOf(item, parent),
   109→  );
   110→}
   111→
   112→/**
   113→ * Collect an item and all its descendants in topological order (parent first).
   114→ * This ensures parent tasks are created before child tasks.
   115→ */
   116→function collectItemsRecursively(
   117→  root: LoadedSpecItem,
   118→  allItems: LoadedSpecItem[],
   119→): LoadedSpecItem[] {
   120→  const result: LoadedSpecItem[] = [root];
   121→  const children = getDirectChildren(root, allItems);
   122→
   123→  for (const child of children) {
   124→    const descendants = collectItemsRecursively(child, allItems);
   125→    result.push(...descendants);
   126→  }
   127→
   128→  return result;
   129→}
   130→
   131→/**
   132→ * Resolve a spec item reference.
   133→ * Returns the spec item or exits with error.
