284→  const graph = new Map<string, string[]>();
285→  const specBySlug = new Map<string, PlanSpec>();
286→
287→  for (const spec of specs) {
288→    const slug = spec.slug || slugify(spec.title);
289→    if (specBySlug.has(slug)) {
290→      return {
291→        sorted: [],
292→        error: {
293→          type: "validation",
294→          message: `Duplicate slug detected: "${slug}". Ensure each spec has a unique slug or title.`,
295→        },
296→      };
297→    }
298→    specBySlug.set(slug, spec);
299→    graph.set(slug, []);
300→  }
301→
302→  // Add edges for parent dependencies
303→  for (const spec of specs) {
304→    const slug = spec.slug || slugify(spec.title);
305→    if (spec.parent) {
306→      const parentRef = spec.parent.startsWith("@") ? spec.parent.slice(1) : spec.parent;
307→
308→      // Only add edge if parent is in this plan (local reference)
309→      if (specBySlug.has(parentRef)) {
310→        const children = graph.get(parentRef) || [];
311→        children.push(slug);
312→        graph.set(parentRef, children);
313→      }
314→    }
315→  }
316→
317→  // Detect cycles using DFS
318→  const visited = new Set<string>();
319→  const recursionStack = new Set<string>();
320→
321→  function hasCycle(node: string, path: string[]): string[] | null {
322→    visited.add(node);
323→    recursionStack.add(node);
324→
325→    const children = graph.get(node) || [];
326→    for (const child of children) {
327→      if (!visited.has(child)) {
328→        const cyclePath = hasCycle(child, [...path, child]);
329→        if (cyclePath) return cyclePath;
330→      } else if (recursionStack.has(child)) {
331→        return [...path, child];
332→      }
333→    }
334→
335→    recursionStack.delete(node);
336→    return null;
337→  }
338→
339→  for (const slug of graph.keys()) {
340→    if (!visited.has(slug)) {
341→      const cyclePath = hasCycle(slug, [slug]);
342→      if (cyclePath) {
343→        const cycleRefs = cyclePath.map(s => `@${s}`).join(" -> ");
344→        return {
345→          sorted: [],
346→          error: {
347→            type: "circular",
348→            message: `Circular parent reference: ${cycleRefs}`,
349→          },
350→        };
351→      }
352→    }
353→  }
354→
355→  // Topological sort using DFS
356→  const sorted: PlanSpec[] = [];
357→  const processed = new Set<string>();
358→
359→  function visit(node: string) {
360→    if (processed.has(node)) return;
361→
362→    const spec = specBySlug.get(node);
363→    if (!spec) return;
364→
365→    // Visit parent first if it's in this plan
366→    if (spec.parent) {
367→      const parentRef = spec.parent.startsWith("@") ? spec.parent.slice(1) : spec.parent;
368→      if (specBySlug.has(parentRef)) {
369→        visit(parentRef);
370→      }
371→    }
372→
373→    processed.add(node);
374→    sorted.push(spec);
375→  }
376→
377→  for (const slug of specBySlug.keys()) {
378→    visit(slug);
379→  }
380→
381→  return { sorted, error: null };
382→}
383→
384→/**
385→ * Simple slugification helper
386→ */
387→function slugify(title: string): string {
388→  return title
389→    .toLowerCase()
390→    .replace(/[^a-z0-9]+/g, "-")
391→    .replace(/^-|-$/g, "");
392→}
393→
394→/**
395→ * Validate parent references.
396→ *
397→ * AC: @plan-import ac-17 - Detect missing parent references
398→ * AC: @plan-import ac-33 - Provide recovery hints
399→ *
400→ * @param specs Specs to validate
401→ * @param existingRefs Set of existing spec refs in the project
402→ * @returns Errors for specs with invalid parents
403→ */
404→export function validateParentRefs(
405→  specs: PlanSpec[],
406→  existingRefs: Set<string>,
407→): ParseError[] {
408→  const errors: ParseError[] = [];
409→  const planSlugs = new Set(
410→    specs.map(s => s.slug || slugify(s.title))
411→  );
412→
413→  for (const spec of specs) {
414→    if (!spec.parent) continue;
415→
416→    const parentRef = spec.parent.startsWith("@") ? spec.parent.slice(1) : spec.parent;
417→
418→    // Check if parent exists in plan or project
419→    if (!planSlugs.has(parentRef) && !existingRefs.has(parentRef)) {
420→      errors.push({
421→        type: "dependency",
422→        message: `Parent ${spec.parent} not found. Check parent exists or define it earlier in plan`,
423→        spec,
424→      });
425→    }
426→  }
427→
428→  return errors;
429→}
