    59→export interface ParsedPlanDocument {
    60→  title: string;
    61→  content: string;
    62→  specs: PlanSpec[];
    63→  tasks: TasksSection;
    64→  implementationNotes: string | null;
    65→  errors: ParseError[];
    66→}
    67→
    68→/**
    69→ * Parse error with context
