    71→export interface ParseError {
    72→  type: "yaml" | "validation" | "dependency" | "circular";
    73→  message: string;
    74→  line?: number;
    75→  specIndex?: number;
    76→  spec?: PlanSpec;
    77→}
    78→
    79→/**
    80→ * Parse a plan document from markdown text.
    81→ *
    82→ * AC: @plan-import ac-11 - Extract and parse ## Specs YAML blocks
    83→ * AC: @plan-import ac-12 - Parse Tasks section for derive_from_specs
    84→ * AC: @plan-import ac-13 - Extract ## Implementation Notes section
    85→ * AC: @plan-import ac-21 - Report YAML parse errors with line numbers
    86→ */
    87→export function parsePlanDocument(content: string): ParsedPlanDocument {
    88→  const errors: ParseError[] = [];
    89→
    90→  // Extract title from first heading
    91→  const titleMatch = content.match(/^#\s+(.+)$/m);
    92→  const title = titleMatch ? titleMatch[1].trim() : "Untitled Plan";
    93→
    94→  // Extract ## Specs section
    95→  const specs = extractSpecsSection(content, errors);
    96→
    97→  // Extract ## Tasks section
    98→  const tasks = extractTasksSection(content, errors);
    99→
   100→  // Extract ## Implementation Notes section
   101→  const implementationNotes = extractImplementationNotes(content);
   102→
   103→  return {
   104→    title,
   105→    content,
   106→    specs,
   107→    tasks,
