   120→function extractSpecsSection(content: string, errors: ParseError[]): PlanSpec[] {
   121→  // Find ## Specs section
   122→  const specsMatch = content.match(/##\s+Specs\s*\n([\s\S]*?)(?=\n##\s+\w|$)/);
   123→
