   139→    return [];
   140→  }
   141→
   142→  const yamlContent = yamlMatch[1];
   143→
   144→  // Parse YAML
   145→  let parsed: unknown;
   146→  try {
   147→    parsed = parseYaml(yamlContent);
   148→  } catch (err) {
